<section class="section-wrap dashboard-page admin-page"><div class="dashboard-heading"><div><p class="eyebrow">FULFILMENT, WITH CARE</p><h1>Orders<span class="brand-dot">.</span></h1><p><?= (int) $total ?> orders in your store.</p></div></div><form class="order-filters" action="<?= $e($base) ?>/admin/orders" method="get"><input name="q" value="<?= $e($_GET['q'] ?? '') ?>" placeholder="Search name or order number"><select name="status"><option value="">Every status</option><?php foreach (['pending','paid','processing','shipped','delivered','cancelled','refunded'] as $status): ?><option value="<?= $status ?>" <?= ($_GET['status'] ?? '') === $status ? 'selected' : '' ?>><?= ucfirst($status) ?></option><?php endforeach; ?></select><button class="button button-dark">Filter</button></form><div class="data-card"><div class="table-head orders-admin-head"><span>Order</span><span>Customer</span><span>Date</span><span>Status</span><span>Total</span><span>Next step</span></div><?php foreach ($orders as $order): ?><div class="table-row orders-admin-head"><b>#<?= (int) $order['id'] ?></b><span><?= $e($order['customer_name']) ?><small><?= $e($order['email']) ?></small></span><span><?= $e(date('M j, Y', strtotime($order['created_at']))) ?></span><span><i class="status-pill status-<?= $e($order['status']) ?>"><?= $e(ucfirst($order['status'])) ?></i></span><b><?= number_format((float) $order['total'], 2) ?> JOD</b><form action="<?= $e($base) ?>/admin/order/status" method="post"><input type="hidden" name="csrf_token" value="<?= $e($csrf_token) ?>"><input type="hidden" name="order_id" value="<?= (int) $order['id'] ?>"><?php $next = ['pending' => ['processing'], 'paid' => ['shipped'], 'processing' => ['shipped'], 'shipped' => ['delivered']][$order['status']] ?? []; ?><?php if ($next): ?><select name="status" aria-label="Update order status"><?php foreach ($next as $status): ?><option value="<?= $status ?>"><?= ucfirst($status) ?></option><?php endforeach; ?></select><button class="mini-action">Update</button><?php else: ?><span class="muted">—</span><?php endif; ?></form></div><?php endforeach; ?><?php if (!$orders): ?><p class="empty-inline">No orders match this view.</p><?php endif; ?></div></section>
